scene.preParsingEffects:
            [##var textClass = COLOUR_COVERING_RED.getClass(); 
				var classLoader = textClass.getClassLoader(); 
				var nightClass = classLoader.loadClass('com.lilithsthrone.game.dialogue.places.dominion.nightlife.NightlifeDistrict'); 
            ]
            [##
				var getClubbersPresent = nightClass.getMethod('getClubbersPresent').invoke(null); 
                if(getClubbersPresent.contains(idol)) getClubbersPresent.remove(idol); 
            ]
            [##
                function likesKiss(partner, isDominantPartner) {
                    return partner.getAffection(pc) >= AFFECTION_POSITIVE_ONE_FRIENDLY.getMedianValue()
                            || partner.getAlcoholLevelValue()>0;
                };
                
                function likesGroping(partner, isDominantPartner) {
                    return partner.getAffection(pc) >= AFFECTION_POSITIVE_TWO_LIKE.getMedianValue()
                            || partner.getAlcoholLevelValue()>ALCOHOL_LEVEL_TWO_MERRY.getMinimumValue();
                };
                
                function likesSex(partner, isDominantPartner) {
                    return partner.getAffection(pc) >= AFFECTION_POSITIVE_THREE_CARING.getMedianValue()
                            || partner.getAlcoholLevelValue()>ALCOHOL_LEVEL_THREE_DRUNK.getMinimumValue();
                };
            ]
            [##
                function isClubOpen(minutesPassedForNextScene) {
                    return !((game.getMinutesPassed()+minutesPassedForNextScene) % (24 * 60) >= (60 * 5) && (game.getMinutesPassed()+minutesPassedForNextScene) % (24 * 60) < (60 * 19));
                };
                function isPartnerLeaving() {
                    return getClubbersPresent.size() != 0 && getClubbersPresent.get(0).getAffection(pc) < AFFECTION_NEGATIVE_THREE_STRONG_DISLIKE.getMedianValue();
                };
                function isPartnerPassingOut(isDominantPartner) {
                    return getClubbersPresent.size() != 0 && !isDominantPartner && getClubbersPresent.get(0).getAlcoholLevelValue() >= ALCOHOL_LEVEL_FIVE_WASTED.getMaximumValue()-0.05;
                };
                function isEndConditionMet(minutesPassedForNextScene) {
                    return isPartnerLeaving() || isPartnerPassingOut(false) || (!isClubOpen(minutesPassedForNextScene) && flags.hasFlag(FLAG_passedJules));
                };
            ]
            [##
                function getClubberStatus(secondsPassedForNextScene, isDominantPartner) {
                    var str = '';
                    if(getClubbersPresent.size() != 0) {
                        var clubber = getClubbersPresent.get(0);
                        
                        var al = clubber.getAffectionLevel(pc);

                        str += "<p style='text-align:center;'><i>";
                        switch(al) {
                            case AFFECTION_NEGATIVE_FIVE_LOATHE:
                            case AFFECTION_NEGATIVE_FOUR_HATE:
                            case AFFECTION_NEGATIVE_THREE_STRONG_DISLIKE:
                            case AFFECTION_NEGATIVE_TWO_DISLIKE:
                                str += "[npc2.Name] looks <i style='color:"+al.getColour().toWebHexString()+";'>angry and frustrated</i>, and will leave you if you continue to treat [npc2.herHim] poorly.";
                                break;
                            case AFFECTION_NEGATIVE_ONE_ANNOYED:
                                str += "[npc2.Name] looks <i style='color:"+al.getColour().toWebHexString()+";'>mildly annoyed</i>, and is starting to have a bad time.";
                                break;
                            case AFFECTION_ZERO_NEUTRAL:
                            case AFFECTION_POSITIVE_ONE_FRIENDLY:
                                str += "[npc2.Name] looks <i style='color:"+al.getColour().toWebHexString()+";'>entertained</i>, and has no reason to leave you.";
                                break;
                            case AFFECTION_POSITIVE_TWO_LIKE:
                            case AFFECTION_POSITIVE_THREE_CARING:
                                str += "[npc2.Name] looks like [npc2.sheIs] <i style='color:"+al.getColour().toWebHexString()+";'>having a great time</i>.";
                                break;
                            case AFFECTION_POSITIVE_FOUR_LOVE:
                            case AFFECTION_POSITIVE_FIVE_WORSHIP:
                                str += "[npc2.NameIsFull] <i style='color:"+al.getColour().toWebHexString()+";'>desperate to have sex with you</i>.";
                                break;
                        };

                        if(clubber.getAlcoholLevelValue()>0) {
                            str += "</br>";
                            switch(clubber.getAlcoholLevel()) {
                                case ALCOHOL_LEVEL_ZERO_SOBER:
                                    break;
                                case ALCOHOL_LEVEL_ONE_TIPSY:
                                    str += "[npc2.Name] is currently <i style='color:"+COLOUR_ALCOHOL.toWebHexString()+";'>tipsy</i>.";
                                    break;
                                case ALCOHOL_LEVEL_TWO_MERRY:
                                    str += "[npc2.Name] is currently <i style='color:"+COLOUR_ALCOHOL.toWebHexString()+";'>merry</i>.";
                                    break;
                                case ALCOHOL_LEVEL_THREE_DRUNK:
                                    str += "[npc2.Name] is currently <i style='color:"+COLOUR_ALCOHOL.toWebHexString()+";'>drunk</i>.";
                                    break;
                                case ALCOHOL_LEVEL_FOUR_HAMMERED:
                                    str += "[npc2.Name] is currently <i style='color:"+COLOUR_ALCOHOL.toWebHexString()+";'>hammered</i>. Giving [npc2.herHim] any more alcohol would be a bad idea.";
                                    break;
                                case ALCOHOL_LEVEL_FIVE_WASTED:
                                    str += "[npc2.Name] is currently <i style='color:"+COLOUR_ALCOHOL.toWebHexString()+";'>wasted</i>."+(isPartnerSub()?" [npc2.She] looks like [npc2.sheIs] going to pass out.":"");
                                    break;
                            };
                        };

                        str += "</br>";
                        if(likesSex(clubber, isDominantPartner)) {
                            str += "You can tell that [npc2.she] wants to have sex with you...";
                            
                        } else if(likesGroping(clubber, isDominantPartner)) {
                            if(isDominantPartner) {
                                str += "You can tell that [npc2.sheIs] about to try and get some physical contact with you...";
                            } else {
                                str += "You can tell that [npc2.she] wants some physical contact...";
                            }
                            
                        } else if(likesKiss(clubber, isDominantPartner)) {
                            if(isDominantPartner) {
                                str += "You can tell that [npc2.sheIs] going to try and kiss you at any moment...";
                            } else {
                                str += "You can tell that [npc2.she] wouldn't mind a kiss...";
                            }
                            
                        } else {
                            if(isDominantPartner) {
                                str += "You can tell that [npc2.sheIs] not yet ready to make a move on you...";
                            } else {
                                str += "It would be best to talk to [npc2.herHim] a little before making a move...";
                            }
                        }
                        
                        str += "</i></p>";
                    };

                    var minutesPassedForNextScene = secondsPassedForNextScene/60;
                    if(isEndConditionMet(clubber, minutesPassedForNextScene)) {
                        str += "<p style='text-align:center;'>";
                        if(isPartnerLeaving(clubber, false)) {
                            str += getClubbersPresent + "[style.boldTerrible([npc2.Name] leaves you!)]</br>"
                                    + "[npc2.Name] is fed up, and with a dismissive wave of [npc2.her] [npc2.hand], [npc2.she] turns around and leaves you!";
                        
                        } else if(isPartnerPassingOut(false)) {
                            str += getClubbersPresent + "[style.boldTerrible([npc2.Name] collapses!)]</br>"
                                    + "Having had far too much to drink, [npc2.name] slumps down to the ground!";
                            
                        } else if(!isClubOpen(minutesPassedForNextScene)) {
                            if(pc.getLocationPlace().getPlaceType().equals(PLACE_TYPE_WATERING_HOLE_VIP_AREA)) {
                                str += getClubbersPresent + "[style.boldTerrible(Closing time)]</br>"
                                        + "All of the lights in the club suddenly flash off and on a few times, and as the background music stops playing, Kruger growls,"
                                            + " [kruger.speech(Looks like it's time to close for the night. Go on, [pc.name]. We can do this another time.)]";
                                
                            } else {
                                str += getClubbersPresent + "[style.boldTerrible(Closing time)]</br>"
                                        + "All of the lights in the club suddenly flash off and on a few times, and as the background music stops playing, you hear Jules shout out, [jules.speech(It's closing time! Everyone out!)]";
                            }
                        }
                        str += "</p>";
                    }
                    
                    return str;
                };
            ]
            [##
                var clubbersList = null;
                if(getClubbersPresent.size() != 0) {
                    clubbersList = getClubbersPresent.get(0);
                }
            ]
            #IF(pc.getCell() == idol.getCell() && !flags.hasSavedLong('temp'))
                [#game.appendToTextEndStringBuilder(game.parseFromFile("mods/xys/txt/idol", "IDOL_BACKGROUND"))]
            #ELSE
                [##flags.removeSavedLong('temp')]
            #ENDIF
            [#game.appendToTextEndStringBuilder(getClubberStatus(60, false))]

response.effects:
[#game.appendToTextStartStringBuilder(game.parseFromFile("txt/places/dominion/nightlife/theWateringHole", "WATERING_HOLE_DANCE_FLOOR_SAVE_CLUBBER", clubbersList))]
[#
    for (var i = 0; i < getClubbersPresent.size(); i++) {
        getClubbersPresent.get(i).setLocation(WORLD_TYPE_EMPTY, PLACE_TYPE_GENERIC_CLUB_HOLDING_CELL);
    };
]

[#game.appendToTextStartStringBuilder(game.parseFromFile("txt/places/dominion/nightlife/theWateringHole", "WATERING_HOLE_DANCE_FLOOR_LOSE_COMPANY", clubbersList))]
[#
    for (var i = 0; i < getClubbersPresent.size(); i++) {
        game.banishNPC(game.getNPCById(getClubbersPresent.get(i).getId()));
    };
]

